# Verifier for F(10)=6. No imports, no I/O, exact integer arithmetic.
# Entry point: verify(witness) — raises on any failed check, returns True on PASS.
# Witness hardcoded below; the harness may also call verify(w) with its own dict.

def covers(A, N):
    D = set()
    for a in A:
        for b in A:
            D.add(a - b)
    for d in range(0, N + 1):
        if d not in D:
            return False
    return True

def verify(witness):
    N = witness['N']
    F = witness['F_N']
    A = witness['A']
    if N != 10:
        raise ValueError('N must be 10')
    if F != 6:
        raise ValueError('F_N must be 6')
    if not isinstance(A, list) or len(A) != F:
        raise ValueError('A must be a list of size F_N=6')
    if len(set(A)) != len(A):
        raise ValueError('A must have distinct elements')
    for x in A:
        if not isinstance(x, int) or not (0 <= x <= N):
            raise ValueError('A elements must be ints in [0,N]')
    if not covers(A, N):
        raise ValueError('A does not cover {0..N}')
    # exhaustive minimality: all C(11,5)=462 five-element subsets
    for a in range(N + 1):
        for b in range(a + 1, N + 1):
            for c in range(b + 1, N + 1):
                for d in range(c + 1, N + 1):
                    for e in range(d + 1, N + 1):
                        if covers([a, b, c, d, e], N):
                            raise ValueError('found 5-element covering subset; F(10) != 6')
    return True

witness = {'N': 10, 'F_N': 6, 'A': [0, 1, 2, 6, 9, 10]}
verify(witness)
